CREATE POLICY technical_photos_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'technical-photos' AND (public.is_admin(auth.uid()) OR public.has_role(auth.uid(), 'atendente') OR public.has_role(auth.uid(), 'producao') OR public.has_role(auth.uid(), 'financeiro')));
CREATE POLICY technical_photos_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'technical-photos' AND (storage.foldername(name))[1] = auth.uid()::text AND (public.is_admin(auth.uid()) OR public.has_role(auth.uid(), 'atendente') OR public.has_role(auth.uid(), 'producao')));
CREATE POLICY technical_photos_delete ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'technical-photos' AND (public.is_admin(auth.uid()) OR ((storage.foldername(name))[1] = auth.uid()::text AND (public.has_role(auth.uid(), 'atendente') OR public.has_role(auth.uid(), 'producao')))));